async def act(page):
    """
    Plan:
    - Use the provided knowledge-base helper export_customers_csv_via_grid to navigate to the Customers management page
      and export the customers grid as CSV. This helper already handles navigation to '/index.php/admin/customer/'.
    - Parse the returned CSV to locate a row whose Telephone (or Phone) column matches 2137418080 (normalize digits).
    - Print the matching customer's Name and Email as a single comma-separated line: "Name,Email".

    Rationale for using the KB function:
    - The export_customers_csv_via_grid helper is specifically designed to export the Customers grid as CSV and is
      the most robust way to retrieve all customers including their telephone numbers. The task requires using KB
      functions when available.
    """
    # Use the KB helper to download/export the customers CSV
    result = await export_customers_csv_via_grid(page, filename='customers.csv')

    csv_text = result.get('csv', '')

    # Defensive: if CSV is empty, output a message
    if not csv_text:
        print('')
        return

    import io, csv, re

    def normalize_phone(s: str) -> str:
        if s is None:
            return ''
        return re.sub(r'\D', '', s)

    target = '2137418080'

    reader = csv.reader(io.StringIO(csv_text))
    try:
        headers = next(reader)
    except StopIteration:
        print('')
        return

    # Normalize header names for lookups
    header_map = {h.strip(): i for i, h in enumerate(headers)}

    # Try common header names
    name_keys = [k for k in header_map.keys() if k.lower() in ('name', 'customer', 'full name')]
    email_keys = [k for k in header_map.keys() if k.lower() in ('email', 'e-mail')]
    phone_keys = [k for k in header_map.keys() if k.lower() in ('telephone', 'phone', 'tel')]

    found = None
    for row in reader:
        # Skip rows that don't match header length by padding
        if len(row) < len(headers):
            row = row + [''] * (len(headers) - len(row))

        # Extract phone using discovered header keys
        phone_val = ''
        for pk in phone_keys:
            phone_val = row[header_map[pk]].strip()
            if phone_val:
                break

        if normalize_phone(phone_val) == target:
            # Extract name and email
            name_val = ''
            email_val = ''
            if name_keys:
                name_val = row[header_map[name_keys[0]]].strip()
            if email_keys:
                email_val = row[header_map[email_keys[0]]].strip()

            # Print exactly Name,Email on a single line
            print(f"{name_val},{email_val}")
            found = (name_val, email_val)
            break

    # If not found, print empty line (no output)
    if not found:
        print('')
    return

